obj={4:{(3,8),(4,7),(4,9),(5,6),(5,7),(5,9)},8:{(1,24),(2,23),(3,23)},2:{(3,14),(4,13),(5,12),(21,22),(21,23)},5:{(9,26),(10,25),(10,26)},6:{(11,6),(12,6),(12,8)},3:{(11,16),(12,17),(13,17)},7:{(19,12),(20,13)},9:{(22,6),(23,4)}}
for co,ps in obj.items():
 for r,c in ps:G[r-1][c-1]=co
# classify and complete same-color local 3x3 square by symmetry from a center point (mirror diagonal), which links the short markers into likely correct transformation.
for co,ps in obj.items():
 if co==4:continue
 for r,c in list(ps):
  for dr,dc in [(1,1),(-1,-1),(1,-1),(-1,1)]:
   rr,cc=r+dr,c+dc
   if 1<=rr<=30 and 1<=cc<=30 and G[rr-1][cc-1]==1:
    # add only if cell completes a mirrored counterpart pair in local structure
    if (r+dr,c) in ps or (r,c+dc) in ps:G[rr-1][cc-1]=co
assert all(len(row)==30 for row in G)
print(json.dumps({'action':'submit','grid':G},separators=(',',':')))

import json
