objs={4:[{(3,8),(4,7),(4,9),(5,6),(5,7),(5,9)}],8:[{(2,24),(3,23),(4,23)}],2:[{(4,14),(5,13),(6,12)},{(22,22),(22,23)}],5:[{(10,26),(11,25),(11,26)}],6:[{(12,6),(13,6),(13,8)}],3:[{(12,16),(13,17),(14,17)}],7:[{(20,12),(21,13)}],9:[{(23,6),(24,4)}]}
T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
def variants(s):
 out=[]
 for f in (0,1):
  for k in range(4):
   q=set()
   for r,c in s:
    if f:c=-c
    for _ in range(k): r,c=c,-r
    q.add((r,c))
   mr=min(r for r,c in q);mc=min(c for r,c in q)
   q=frozenset((r-mr,c-mc) for r,c in q)
   if q not in out:out.append(q)
 return out
V=variants(T)
for col,groups in objs.items():
 for ps in groups:
  for r,c in ps:G[r-1][c-1]=col
for col,groups in objs.items():
 if col==4:continue
 for ps in groups:
  opts=[]
  r0=min(r for r,c in ps);c0=min(c for r,c in ps)
  for vi,s in enumerate(V):
   for r in range(1,31):
    for c in range(1,31):
     cells={(r+dr,c+dc) for dr,dc in s}
     if max(x for x,y in cells)>30 or max(y for x,y in cells)>30:continue
     if ps<=cells:
      opts.append((abs(r-r0)+abs(c-c0),vi,r,c,cells))
  if not opts:continue
  _,vi,r,c,cells=min(opts,key=lambda x:(x[0],x[1],x[2],x[3]))
  for rr,cc in cells:
   if G[rr-1][cc-1] in (1,col):G[rr-1][cc-1]=col
print(json.dumps({'action':'submit','grid':G},separators=(',',':')))

